#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr;
    long num = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    if (num < 0 || num > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    double low = 0.0;
    double high = (double)num;
    double mid;
    int iter = 0;
    while (iter < 100) {
        mid = (low + high) / 2.0;
        if ((double)num < mid * mid) {
            high = mid;
        } else {
            low = mid;
        }
        iter++;
    }
    printf("%.6f\n", mid);
    return 0;
}
